-- ┌──────────────────────────────────────────────┐
-- │  hyprland.lua — flat, fast, wallpaper-themed │
-- └──────────────────────────────────────────────┘
-- Colors come from matugen (~/.config/hypr/colors.lua, regenerated by `wall`).
-- Keybinds live in binds.lua. Machine-specific extras go in local.lua (see local.lua.example).

local HOME = os.getenv("HOME")
local hypr = HOME .. "/.config/hypr/"

-- Load generated palette; fall back to neutral greys if matugen hasn't run yet.
local ok, c = pcall(dofile, hypr .. "colors.lua")
if not ok or type(c) ~= "table" then
    c = {
        primary                = "rgb(a6c8ff)",
        surface                = "rgb(111318)",
        surface_container_high = "rgb(282a2f)",
        outline_variant        = "rgb(44474e)",
        error                  = "rgb(ffb4ab)",
    }
end


---------------------------------------------------------------- MONITORS ----
-- Every output at its preferred mode. Set resolution / refresh / scale per monitor in
-- rice-settings → display (it writes settings.lua, loaded at the bottom), or in local.lua.
hl.monitor({ output = "", mode = "preferred", position = "auto", scale = "auto" })


------------------------------------------------------------------- ENV ----
hl.env("XCURSOR_THEME",   "Bibata-Modern-Classic")
hl.env("XCURSOR_SIZE",    "24")
hl.env("HYPRCURSOR_THEME","Bibata-Modern-Classic")
hl.env("HYPRCURSOR_SIZE", "24")
hl.env("QT_QPA_PLATFORM", "wayland;xcb")
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")
hl.env("QT_WAYLAND_DISABLE_WINDOWDECORATION", "1")
hl.env("GDK_BACKEND",     "wayland,x11,*")
hl.env("ELECTRON_OZONE_PLATFORM_HINT", "auto")
-- GTK4: GL renderer. The default Vulkan one wakes the sleeping NVIDIA dGPU on every
-- launch (~2 s delay on rice-wallpicker, Files, Settings…) and costs battery.
hl.env("GSK_RENDERER",    "gl")

-- PATH: prepend ~/.local/bin exactly once (a plain prepend grows on every reload)
local prepend = {
    HOME .. "/.local/bin",
}
local skip, parts = {}, {}
for _, d in ipairs(prepend) do skip[d] = true; parts[#parts + 1] = d end
for d in string.gmatch(os.getenv("PATH") or "/usr/local/bin:/usr/bin", "[^:]+") do
    if not skip[d] then skip[d] = true; parts[#parts + 1] = d end
end
hl.env("PATH", table.concat(parts, ":"))


------------------------------------------------------------- AUTOSTART ----
hl.on("hyprland.start", function()
    hl.exec_cmd("dbus-update-activation-environment --systemd GSK_RENDERER")  -- D-Bus-launched GTK apps (Files…)
    hl.exec_cmd("awww-daemon")
    hl.exec_cmd("sleep 0.4 && wall restore")
    hl.exec_cmd("waybar")
    hl.exec_cmd("mako")
    hl.exec_cmd("hypridle")
    hl.exec_cmd("rice-battery daemon")  -- battery history + profile switch on plug/unplug
    hl.exec_cmd("systemctl --user start hyprpolkitagent")
    hl.exec_cmd("nm-applet --indicator")
    hl.exec_cmd("wl-paste --type text  --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
end)


-- new monitor plugged in → awww leaves it black until told; re-apply the wallpaper
hl.on("monitor.added", function()
    hl.exec_cmd("sleep 0.5 && wall restore")
end)

---------------------------------------------------------- LOOK & FEEL ----
hl.config({
    general = {
        gaps_in     = 3,
        gaps_out    = 2,
        border_size = 1,
        col = {
            active_border   = c.primary,
            inactive_border = c.surface_container_high,
        },
        resize_on_border = true,
        allow_tearing    = false,
        layout           = "dwindle",
    },

    -- Flat: no blur, no shadows, small radius.
    decoration = {
        rounding         = 6,
        rounding_power   = 2,
        active_opacity   = 1.0,
        inactive_opacity = 1.0,
        dim_inactive     = false,
        shadow = { enabled = false },
        blur   = { enabled = false },
    },

    animations = { enabled = true },

    dwindle = {
        preserve_split = true,
        force_split    = 2,   -- new windows open right/bottom
    },
    master = { new_status = "master" },

    misc = {
        force_default_wallpaper   = 0,
        disable_hyprland_logo     = true,
        disable_splash_rendering  = true,
        background_color          = c.surface,
        focus_on_activate         = true,
        animate_manual_resizes    = false,
        middle_click_paste        = false,
        enable_swallow            = true,
        swallow_regex             = "^(kitty)$",
    },

    cursor   = { hide_on_key_press = true, inactive_timeout = 5 },
    xwayland = { force_zero_scaling = true },
    binds    = { workspace_back_and_forth = true },

    ecosystem = {
        no_update_news  = true,
        no_donation_nag = true,
    },

    input = {
        kb_layout    = "us",
        follow_mouse = 1,
        sensitivity  = 0,
        touchpad = {
            natural_scroll       = true,
            tap_to_click         = true,
            disable_while_typing = true,
            clickfinger_behavior = true, -- 2-finger click = right click
            scroll_factor        = 0.6,
        },
    },
})

hl.gesture({ fingers = 3, direction = "horizontal", action = "workspace" })


------------------------------------------------------------ ANIMATIONS ----
-- Short and decisive. Nothing bounces, nothing lingers.
hl.curve("snap",   { type = "bezier", points = { {0.2, 0.9}, {0.1, 1.0} } })
hl.curve("linear", { type = "bezier", points = { {0, 0},     {1, 1}     } })

hl.animation({ leaf = "global",     enabled = true, speed = 3,   bezier = "snap" })
hl.animation({ leaf = "windowsIn",  enabled = true, speed = 2.5, bezier = "snap",   style = "popin 94%" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 1.5, bezier = "linear", style = "popin 94%" })
hl.animation({ leaf = "windowsMove",enabled = true, speed = 2.5, bezier = "snap" })
hl.animation({ leaf = "border",     enabled = true, speed = 3,   bezier = "snap" })
hl.animation({ leaf = "fade",       enabled = true, speed = 2,   bezier = "snap" })
hl.animation({ leaf = "layers",     enabled = true, speed = 2,   bezier = "snap",   style = "fade" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 2.5, bezier = "snap",   style = "slide" })
hl.animation({ leaf = "specialWorkspace", enabled = true, speed = 2.5, bezier = "snap", style = "slidevert" })


----------------------------------------------------------------- RULES ----
hl.window_rule({ name = "suppress-maximize", match = { class = ".*" }, suppress_event = "maximize" })

hl.window_rule({
    name  = "fix-xwayland-drags",
    match = { class = "^$", title = "^$", xwayland = true, float = true, fullscreen = false, pin = false },
    no_focus = true,
})

-- Small utility windows float, centered
for _, cls in ipairs({
    "^(org.pulseaudio.pavucontrol|pavucontrol)$",
    "^(nm-connection-editor)$",
    "^(kitty-float)$",
    "^(blueman-manager)$",
    "^(nwg-look)$",
    "^(qt5ct|qt6ct)$",
    "^(xdg-desktop-portal-gtk)$",
    "^(org.kde.polkit-kde-authentication-agent-1|hyprpolkitagent)$",
}) do
    hl.window_rule({ name = "float-" .. cls, match = { class = cls }, float = true, center = true })
end

hl.window_rule({ name = "float-dialogs", match = { title = "^(Open File|Save As|Open Folder|File Upload.*)$" }, float = true, center = true })

-- File pickers (GTK portal: Code OSS, browsers, etc.) open nearly full-height by default.
-- Keep them a comfortable, centred size.
hl.window_rule({
    name  = "file-picker-size",
    match = { class = "^(xdg-desktop-portal-gtk|xdg-desktop-portal-gnome)$" },
    size  = "(monitor_w*0.55) (monitor_h*0.62)",
    center = true,
})
hl.window_rule({
    name  = "file-dialog-size",
    match = { title = "^(Open File|Open Files|Save As|Save File|Open Folder|Select Folder|File Upload.*)$" },
    size  = "(monitor_w*0.55) (monitor_h*0.62)",
    center = true,
})
hl.window_rule({ name = "pip",  match = { title = "^(Picture-in-Picture|Picture in picture)$" }, float = true, pin = true })

-- Wallpaper carousel (rice-wallpicker): floating, centred, borderless, focus-grabbing
hl.window_rule({
    name  = "wallpicker",
    match = { class = "^(rice.wallpicker)$" },
    float = true, center = true, pin = true,
    border_size = 0, no_shadow = true, dim_around = true, stay_focused = true,
})

-- rice-settings (SUPER+I): floating, centred
hl.window_rule({ name = "rice-settings", match = { class = "^(rice.settings)$" }, float = true, center = true })

-- rice-calendar (waybar clock popup): floating, pinned, centred under the bar
hl.window_rule({
    name  = "rice-calendar",
    match = { class = "^(rice.calendar)$" },
    float = true, pin = true,
    move  = "((monitor_w-window_w)/2) 34",
})

-- lyra (waybar music popup): floating, pinned, top-right under the bar
hl.window_rule({
    name  = "lyra",
    match = { class = "^(rice.lyra)$" },
    float = true, pin = true,
    move  = "(monitor_w-window_w-6) 34",
})

-- rice-battery (waybar battery popup): floating, pinned, top-right under the bar
hl.window_rule({
    name  = "rice-battery",
    match = { class = "^(rice.battery)$" },
    float = true, pin = true,
    move  = "(monitor_w-window_w-6) 34",
})

-- rice-overview (SUPER+Tab): covers the whole monitor, bar included
hl.window_rule({
    name  = "rice-overview",
    match = { class = "^(rice.overview)$" },
    float = true, pin = true,
    size  = "monitor_w monitor_h",
    move  = "0 0",
    no_anim = true, border_size = 0, rounding = 0, no_shadow = true,
})

-- rice-toy widgets (kitty --class rice.*): SUPER+ALT+P pipes
for _, cls in ipairs({ "pipes" }) do
    hl.window_rule({
        name  = "rice-" .. cls,
        match = { class = "^(rice." .. cls .. ")$" },
        float = true, center = true,
        size  = "(monitor_w*0.55) (monitor_h*0.6)",
    })
end

-- Keep the bar/launcher crisp: no animation on the launcher popping in.
hl.layer_rule({ name = "launcher-noanim", match = { namespace = "^launcher$" }, no_anim = true })


----------------------------------------------------------------- BINDS ----
dofile(hypr .. "binds.lua")

-------------------------------------------------- RICE-SETTINGS ----
-- Overrides written by the rice-settings app. Loaded last so they win.
pcall(dofile, hypr .. "settings.lua")

-- Your own additions (monitors, extra binds, app rules). Not touched by updates.
pcall(dofile, hypr .. "local.lua")
